import 'dart:convert';

import 'package:latlong2/latlong.dart';

class DistrictBoundaryData {
  const DistrictBoundaryData({
    required this.name,
    required this.province,
    required this.center,
    required this.encoded,
  });

  final String name;
  final int province;
  final LatLng center;
  final String encoded;

  List<LatLng> get points =>
      _boundaryCache.putIfAbsent(encoded, () => _decodeBoundary(encoded));
}

final Map<String, List<LatLng>> _boundaryCache = {};

List<LatLng> _decodeBoundary(String encoded) {
  final bytes = base64Decode(encoded);
  var index = 0;
  var latitude = 0;
  var longitude = 0;
  int readValue() {
    var value = 0;
    var shift = 0;
    while (index < bytes.length) {
      final byte = bytes[index++];
      value |= (byte & 0x7f) << shift;
      if ((byte & 0x80) == 0) break;
      shift += 7;
    }
    return (value >> 1) ^ -(value & 1);
  }

  final points = <LatLng>[];
  while (index < bytes.length) {
    latitude += readValue();
    longitude += readValue();
    points.add(LatLng(latitude / 100000, longitude / 100000));
  }
  return List<LatLng>.unmodifiable(points);
}

const provinceNames = <int, String>{
  1: 'Koshi',
  2: 'Madhesh',
  3: 'Bagmati',
  4: 'Gandaki',
  5: 'Lumbini',
  6: 'Karnali',
  7: 'Sudurpashchim',
};

final List<DistrictBoundaryData> nepalDistrictBoundaries =
    (jsonDecode(_districtBoundaryJson) as List).map((raw) {
  final item = Map<String, dynamic>.from(raw as Map);
  final center = item['c'] as List;
  return DistrictBoundaryData(
    name: item['n'] as String,
    province: item['p'] as int,
    center: LatLng(
      (center[0] as num).toDouble(),
      (center[1] as num).toDouble(),
    ),
    encoded: item['e'] as String,
  );
}).toList(growable: false);

